import{_ as t,a,c as r,ac as s}from"./chunks/framework.BSuaGltH.js";const k=JSON.parse('{"title":"网络：地址、端口、DNS 与基本观察","description":"网络配置与诊断从一条具体连接开始：谁在什么时间，以哪个源地址连接哪个目标与端口。把 DNS、路由、传输连接和 TLS 分开观察，才能避免用 ping 成功推断应用可用。","frontmatter":{"title":"网络：地址、端口、DNS 与基本观察","description":"网络配置与诊断从一条具体连接开始：谁在什么时间，以哪个源地址连接哪个目标与端口。把 DNS、路由、传输连接和 TLS 分开观察，才能避免用 ping 成功推断应用可用。","showdocs":{"topics":[{"id":"network","title":"网络配置与诊断","link":"/topics/network/"}],"kind":"知识专题","scope":"general","audience":"general","group":"容器与运维","seriesTitle":"网络：分层、寻址与证据","summary":"网络配置与诊断从一条具体连接开始：谁在什么时间，以哪个源地址连接哪个目标与端口。把 DNS、路由、传输连接和 TLS 分开观察，才能避免用 ping 成功推断应用可用。","status":"active","related":[{"title":"网络：离线推演 DNS 与双向路径证据","link":"/systems/network-remote/network/plus/practice/application","kind":"应用实践","scope":"general","audience":"general"},{"title":"网络配置与诊断 操作与命令","link":"/systems/network-remote/network/plus/ecosystem/network-general-general","kind":"命令与对象入口","scope":"general","audience":"general"},{"title":"OSI 与 TCP/IP 分层笔记","link":"/systems/network-remote/network/plus/subjects/networkengineerbase","kind":"知识专题","scope":"general","audience":"general"},{"title":"TCP/IP","link":"/systems/network-remote/network/plus/subjects/tcpip","kind":"知识专题","scope":"general","audience":"general"},{"title":"网络：分层、路由、TCP 与 TLS","link":"/systems/network-remote/network/base/intermediate/mechanisms","kind":"知识专题","scope":"general","audience":"general"}],"prev":false,"next":{"text":"网络：分层、路由、TCP 与 TLS","link":"/systems/network-remote/network/base/intermediate/mechanisms"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":false,"next":{"text":"网络：分层、路由、TCP 与 TLS","link":"/systems/network-remote/network/base/intermediate/mechanisms"}},"headers":[],"relativePath":"systems/network-remote/network/base/basic/start.md","filePath":"systems/network-remote/network/base/basic/start.md"}'),n={name:"systems/network-remote/network/base/basic/start.md"};function o(i,e,l,d,c,m){return a(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="网络-地址、端口、dns-与基本观察" tabindex="-1">网络：地址、端口、DNS 与基本观察 <a class="header-anchor" href="#网络-地址、端口、dns-与基本观察" aria-label="Permalink to &quot;网络：地址、端口、DNS 与基本观察&quot;">​</a></h1><p>网络配置与诊断从一条具体连接开始：谁在什么时间，以哪个源地址连接哪个目标与端口。把 DNS、路由、传输连接和 TLS 分开观察，才能避免用 ping 成功推断应用可用。</p><h2 id="learning-path" tabindex="-1">按任务阅读 <a class="header-anchor" href="#learning-path" aria-label="Permalink to &quot;按任务阅读 {#learning-path}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>当前任务</th><th>阅读内容</th><th>应掌握的结果</th></tr></thead><tbody><tr><td>认识环境与基本操作</td><td>本篇的环境前提、基本对象与操作</td><td>说明管理的对象、执行身份和配置位置</td></tr><tr><td>理解机制并完成配置</td><td><a href="/systems/network-remote/network/base/intermediate/mechanisms">分层、路由、TCP 与 TLS</a>；<a href="/systems/network-remote/network/plus/practice/application">配置连接与双向路径验证</a></td><td>解释关键机制，按配置完成任务并核对结果</td></tr><tr><td>维护、排障与恢复</td><td><a href="/systems/network-remote/network/troubleshooting#part-1">网络变更、证据留存与恢复</a>；<a href="/systems/network-remote/network/troubleshooting#part-2">解析失败、拒绝与超时定位</a>；<a href="/systems/network-remote/network/pro/review/review">能 ping 但业务连接失败的复盘</a></td><td>能保存证据、控制变更、恢复并验收</td></tr></tbody></table><h2 id="layers" tabindex="-1">分层诊断 <a class="header-anchor" href="#layers" aria-label="Permalink to &quot;分层诊断 {#layers}&quot;">​</a></h2><p>先画出客户端、网关、解析器和服务端。链路负责相邻节点，IP负责跨网段寻址，传输层把数据交给端口，应用协议再解释消息。某一层成功只排除了该层的一部分故障：收到HTTP错误说明已有应用响应，不能因此认定所有网络路径正常。把现象标到发生的层，避免看到超时就重装客户端。</p><h2 id="tools" tabindex="-1">工具选择与观察位置 <a class="header-anchor" href="#tools" aria-label="Permalink to &quot;工具选择与观察位置 {#tools}&quot;">​</a></h2><p>选择工具前写出问题：Linux的ip route观察路由，Windows的Get-NetRoute观察路由对象，macOS的route查看路径；它们的参数不能互换。只读观测也受权限和命名空间影响，容器内与宿主机是不同观察点。本课程只展示概念与离线材料，不发包、不运行产品命令。</p><h2 id="addresses" tabindex="-1">地址、前缀与保留网段 <a class="header-anchor" href="#addresses" aria-label="Permalink to &quot;地址、前缀与保留网段 {#addresses}&quot;">​</a></h2><p>CIDR以前缀长度划定网段；192.0.2.0/24是文档示例，不能直接拿来部署。IPv4常见广播网段中末地址是广播，不能当网关；/31点到点等有专门语义。172.12与172.13不属于RFC1918的172.16/12私网，历史公司地址不应复制到新环境。IPv6使用前缀和邻居发现，不能套IPv4广播规则。</p><h2 id="exercise" tabindex="-1">练习与参考解答 <a class="header-anchor" href="#exercise" aria-label="Permalink to &quot;练习与参考解答 {#exercise}&quot;">​</a></h2><p>练习：材料：同一客户端对目标返回HTTP 403，另一次查询得到目标IPv4地址。哪条证据能证明应用层已有响应？还应记录哪两个字段，才能区分命中了错误入口与正确入口的授权拒绝？</p><details class="details custom-block"><summary>参考解答</summary><p>403证明该次请求已有HTTP响应，DNS成功仅证明该次解析获得地址，二者都不证明业务获准。记录实际连接的目标IP/端口和响应来源/请求Host（HTTPS还需预期名称与SNI），再与入口配置对应；不能因为解析成功就把403归为网络不通。</p></details>',13)])])}const h=t(n,[["render",o]]);export{k as __pageData,h as default};
